import { mapBaseHikingToFront } from '@apps/Hiking/@mappers/hiking.mapper';
import { mapFinanceReceiptItemBaseToFront } from '@apps/Hiking/@mappers/hikingFinances.mapper';
import { mapRecipeToFront } from '@apps/Recipes/@mappers/recipes.mapper';
import { mapBaseUserJoinedToFront } from '@apps/Users/@mappers/user.mappers';

import {
  IBaseProductDTO,
  IProductAddDTO,
  IProductDTO,
  IProductStatDTO,
  IProductUpdateDTO,
} from '../@types/products.backTypes';
import { IProduct, IProductFull, IProductStat } from '../@types/products.types';

export const mapBackProductToFront = (backData: IProductDTO): IProductFull => {
  return {
    id: +backData.id,
    name: backData.name,
    carbs: +backData.carbohydrates,
    protein: +backData.protein,
    fat: +backData.fat,
    energy: +backData.energy,
    search_regex: backData.search_regex,
  };
};

export const mapFrontProductToBackAdd = (frontData: IProductFull): IProductAddDTO => {
  return {
    name: frontData.name,
    protein: frontData.protein,
    fat: frontData.fat,
    carbohydrates: frontData.carbs,
    energy: frontData.energy,
    search_regex: frontData.search_regex,
  };
};

export const mapFrontProductToBackUpdate = (frontData: IProductFull): IProductUpdateDTO => {
  return {
    ...mapFrontProductToBackAdd(frontData),
    id: frontData.id,
  };
};

export const mapBaseProductJoinedToFront = (backData: IBaseProductDTO): IProduct => {
  return {
    id: +backData.product_id,
    name: backData.product_name,
    carbs: +backData.product_carbohydrates,
    protein: +backData.product_protein,
    fat: +backData.product_fat,
    energy: +backData.product_energy,
  };
};

export const mapBackProductStatToFront = (backData: IProductStatDTO): IProductStat => {
  return {
    recipes: backData.recipes.map((d) => ({
      id: +d.id,
      amount: +d.amount,
      recipe: mapRecipeToFront(d),
    })),
    force: backData.force.map((d) => ({
      id: +d.id,
      user: mapBaseUserJoinedToFront(d),
      hiking: mapBaseHikingToFront(d),
    })),
    source_product: backData.source_product.map((d) => ({
      id: +d.id,
      rate: +d.rate,
      comment: d.comment,
      hiking: mapBaseHikingToFront(d),
      product: mapBaseProductJoinedToFront(d),
    })),
    target_product: backData.target_product.map((d) => ({
      id: +d.id,
      rate: +d.rate,
      comment: d.comment,
      hiking: mapBaseHikingToFront(d),
      product: mapBaseProductJoinedToFront(d),
    })),
    shopping: backData.shopping.map((d) => ({
      id: +d.id,
      price: +d.price,
      comment: d.comment,
      date: new Date(d.updated_at),
      hiking: mapBaseHikingToFront(d),
      user: mapBaseUserJoinedToFront(d),
    })),
    receipt_items: backData.receipt_items.map((d) => ({
      id: +d.id,
      item: mapFinanceReceiptItemBaseToFront(d),
      hiking: mapBaseHikingToFront(d),
      id_receipt: +d.id_receipt,
    })),
  };
};
